class Solution {long long choose(int n,int r){if(r<0||r>n)return 0;r=min(r,n-r);long long v=1;for(int i=1;i<=r;++i)v=v*(n-r+i)/i;return v;}
 public:int waysToReachStair(int k){long long ans=0;for(int j=0;j<=32;++j){long long down=(1LL<<j)-k;if(down>=0&&down<=j+1)ans+=choose(j+1,(int)down);}return (int)ans;}
};
